{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Tolfenamic acid, a lipophilic aromatic amide/carboxylic acid, has an absolute oral bioavailability of 55.6% in healthy volunteers, supporting high F for the query's aromatic amide-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Tenoxicam, a heteroaromatic amide/enol with a pyridyl group, is essentially 100% orally bioavailable in humans, indicating that this class of heteroaromatic amides can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Bromazepam, a pyridyl-substituted heteroaromatic amide/lactam, has an absolute oral bioavailability of 86% in humans, supporting high F for the query's pyridine-containing amide system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "CP-409,092, which contains an amide and an indole/heteroaromatic core, shows 69% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Vonoprazan, a pyridine-containing heteroaromatic drug, has an estimated human oral bioavailability of 36%, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Labetalol, an aryl amide with phenolic and basic ethanolamine groups, has low oral bioavailability (4–17%, mean 9%) due to extensive first-pass metabolism; this is the main contradictory evidence, but the query lacks labetalol's metabolically labile phenolic/basic side-chain features.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of high-transfer human bioavailability evidence from structurally related heteroaromatic amides and pyridine-containing drugs supports F >= 20% for the query. The only clear low-F outlier, labetalol, is structurally distinct in its phenolic ethanolamine motif and is outweighed by consistent high-F analogues.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule; prediction relies on transferable human data from related heteroaromatic amides.",
    "First-pass metabolism of the query is not directly measured; labetalol demonstrates that some amide-containing molecules can have low F, so metabolic stability remains an uncertainty.",
    "The sulpiride record appears structurally inconsistent with its listed SMILES and was not used as primary evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

